/**
 * The request id: one per incoming request, generated by the server.
 *
 * `proxy.ts` stamps it on the request (for the route handler or page that
 * serves it) and on the response (so a person reporting a problem can quote
 * it). The application log and, from M12's audit slices on, the audit table
 * carry the same value, which is what lets one be found from the other.
 *
 * **The client never chooses it.** The proxy overwrites whatever arrived under
 * this header before anything downstream reads it, so a caller cannot make
 * their request share an id with somebody else's. `requestIdFrom` still checks
 * the shape and falls back to a fresh id, for a request the proxy did not see.
 *
 * Dependency-free on purpose: the proxy imports it, and so does the bare-Node
 * self-check in `scripts/check-logging.mts`.
 */

/** Lower-case, as `Headers` normalises names. Sent to clients as `X-Request-Id`. */
export const REQUEST_ID_HEADER = "x-request-id";

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isRequestId(value: string | null | undefined): value is string {
  return typeof value === "string" && UUID_PATTERN.test(value);
}

export function newRequestId(): string {
  return crypto.randomUUID();
}

/**
 * The id the proxy stamped on this request, or a fresh one when there is none
 * or it is not a UUID -- never an arbitrary string from the header.
 */
export function requestIdFrom(headers: Headers): string {
  const value = headers.get(REQUEST_ID_HEADER);
  return isRequestId(value) ? value.toLowerCase() : newRequestId();
}
